def hashes():
    result = {}
    for name in BEFORE:
        try:
            result[name] = hashlib.sha256((ROOT / name).read_bytes()).hexdigest()
        except OSError as error:
            raise SystemExit(f'Cannot read {name}: {error}')
    return result


def run():
    current = hashes()
    if current == AFTER:
        print('Local native-content support is already installed; nothing changed.')
        return
    if current != BEFORE:
        different = [name for name in BEFORE if current[name] != BEFORE[name]]
        print('Refusing to patch: this checkout differs from the tested fork.', file=sys.stderr)
        for name in different:
            print('  ' + name, file=sys.stderr)
        raise SystemExit('Update the patch for this checkout; no files were changed.')
    data = PATCH.encode('utf-8')
    try:
        subprocess.run(['git', 'apply', '--check', '-'], cwd=ROOT, input=data, check=True)
        subprocess.run(['git', 'apply', '-'], cwd=ROOT, input=data, check=True)
    except (OSError, subprocess.CalledProcessError) as error:
        raise SystemExit(f'Could not apply the content patch: {error}')
    if hashes() != AFTER:
        raise SystemExit('Unexpected post-patch hashes: stop the build and inspect the checkout.')
    print('Installed local native-content support in this checkout. No mod assets were uploaded.')


if __name__ == '__main__':
    run()
